package player;
import CLib.*;import Equipment.*;import coreLG.*;import model.PlayerInfo;import com.badlogic.gdx.*;import com.badlogic.gdx.backends.lwjgl3.*;import com.badlogic.gdx.graphics.*;import com.badlogic.gdx.graphics.g2d.*;import com.teamobi.mobiarmy2.MainGame;
public class KingKongNativeReference extends MainGame {
static Throwable failure; mGraphics g; PlayerEquip[] outfits=new PlayerEquip[10];int frames;
public void create(){try{super.create();g=new mGraphics(new SpriteBatch());TerrainMidlet.myInfo=new PlayerInfo();String root=System.getProperty("review.root");CCanvas.readMess(java.nio.file.Files.readAllBytes(java.nio.file.Path.of(root,"verification/thor-catalog.bin")),(byte)1);String[] names={"yellowP","cuteGirl","greenP","conKhiP","rocketer","robot","ga","tazz","apache","cowg"};int[] heads={26,19,23,24,25,21,21,22,22,19};for(int i=0;i<10;i++){byte[] body=java.nio.file.Files.readAllBytes(java.nio.file.Path.of(root,"server/res/player/"+names[i]+".png"));CPlayer.pImg[i]=new mImage(CLib.Image.createImage(body,0,body.length));byte[] atlas=java.nio.file.Files.readAllBytes(java.nio.file.Path.of(root,"server/res/bigImage"+i+".png"));PlayerEquip.imgData[i]=new mImage(CLib.Image.createImage(atlas,0,atlas.length));short c=(short)i,h=(short)heads[i];outfits[i]=new PlayerEquip(new short[][]{{c,0,(short)(h+2)},{c,1,h},{c,2,(short)(h+1)},{c,3,-1},{c,4,-1}});}}catch(Throwable t){failure=t;t.printStackTrace();Gdx.app.exit();}}
public void render(){if(failure!=null)return;try{Gdx.gl.glClearColor(.06f,.09f,.15f,1);Gdx.gl.glClear(GL20.GL_COLOR_BUFFER_BIT);OrthographicCamera c=new OrthographicCamera();c.setToOrtho(true,1200,240);g.g.setProjectionMatrix(c.combined);mGraphics.zoomLevel=4;g.begin();for(int i=0;i<10;i++){outfits[3].paintFace(15+i*30,42,0,i,g);}g.end();if(++frames==12){Pixmap p=Pixmap.createFromFrameBuffer(0,0,1200,240);PixmapIO.writePNG(Gdx.files.absolute(System.getProperty("review.root")+"/art/concepts/thor-all-classes/kingkong-native-ten-reference.png"),p,-1,true);p.dispose();Gdx.app.exit();}}catch(Throwable t){failure=t;t.printStackTrace();Gdx.app.exit();}}
public static void main(String[] a){Lwjgl3ApplicationConfiguration c=new Lwjgl3ApplicationConfiguration();c.setInitialVisible(false);c.setWindowedMode(1200,240);c.disableAudio(true);new Lwjgl3Application(new KingKongNativeReference(),c);if(failure!=null)System.exit(1);}}
